import sys,csv,collections
rows=list(csv.DictReader(open('responses.csv')))
for S in ['8,64','64,4','4,64,25,81','16,32,2,8','100,1,16','83,38,58,68']:
  c=collections.defaultdict(list)
  for r in rows:
    if r['number_set']==S: c[int(r['target'])].append(int(r['rating']))
  print(S, ' '.join(f'{t}:{sum(v)}/{len(v)}' for t,v in sorted(c.items())))
"

